#!/usr/bin/env python3
"""Stamp each packaged app with its version and build time."""
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
version = json.loads((root / "mygo.json").read_text())["version"]
(root / "cmd/taskboard/version_generated.go").write_text(
    '// Code generated by scripts/generate_version.py; DO NOT EDIT.\n'
    'package main\n\n'
    f'const appVersion = "v{version}"\n'
)

# The Playground is a separate bundle with its own version, so it gets its own
# constant; without this it would show the production version on screen while
# Finder reports a different one.
playground = json.loads((root / "playground/mygo.json").read_text())["version"]
(root / "cmd/taskboard/version_playground_generated.go").write_text(
    '//go:build motionplayground\n\n'
    '// Code generated by scripts/generate_version.py; DO NOT EDIT.\n'
    'package main\n\n'
    f'const playgroundVersion = "v{playground}"\n'
)
